import { expect, test, type Browser, type Page } from '@playwright/test';

// A complete game in which X wins three boards in a row on move 23. Each move is
// [board, cell]; X opens and the players alternate. Generated by playing random legal
// games against backend/rules.js, so every move is legal under the forced-board rule.
const X_WINS: [number, number][] = [
  [3, 8], [8, 0], [0, 4], [4, 1], [1, 6], [6, 1], [1, 7], [7, 8], [8, 2], [2, 0], [0, 2], [2, 2],
  [2, 4], [4, 8], [8, 5], [5, 0], [0, 6], [6, 2], [2, 7], [7, 2], [2, 1], [1, 1], [1, 8],
];

const randomRoom = () => String(100000 + Math.floor(Math.random() * 900000));

async function openPlayer(browser: Browser, room: string) {
  const context = await browser.newContext({ baseURL: 'http://localhost:5173' });
  // The UI defaults to Dutch; the assertions below use the English strings.
  await context.addInitScript(() => localStorage.setItem('uttt-locale', 'en'));
  const page = await context.newPage();
  await page.goto(`/${room}`);
  return page;
}

const cell = (page: Page, board: number, index: number) =>
  page.locator(`[data-board="${board}"][data-cell="${index}"]`);

/** Seats a host (X) and a guest (O) in a fresh room and starts the game for both. */
async function startGame(browser: Browser) {
  const room = randomRoom();
  const host = await openPlayer(browser, room);
  await expect(host.getByRole('heading', { name: "You're playing X" })).toBeVisible();

  const guest = await openPlayer(browser, room);
  await expect(guest.getByRole('heading', { name: "You're playing O" })).toBeVisible();
  await expect(host.getByText('The other player has joined.', { exact: true })).toBeVisible();

  await host.getByRole('button', { name: 'Start game' }).click();
  await guest.getByRole('button', { name: 'Start game' }).click();
  await expect(host.getByRole('heading', { name: 'Your move' })).toBeVisible();
  await expect(guest.getByRole('heading', { name: 'Their move' })).toBeVisible();
  return { host, guest };
}

/** Plays moves in turn and checks each one shows up on both screens. */
async function playMoves(host: Page, guest: Page, moves: [number, number][]) {
  for (const [i, [board, index]] of moves.entries()) {
    const [mover, watcher] = i % 2 === 0 ? [host, guest] : [guest, host];
    await cell(mover, board, index).click();
    await expect(cell(watcher, board, index)).toHaveAttribute('aria-label', /: (X|O)/);
    await expect(watcher.getByText(`Move ${i + 1}`)).toBeVisible();
  }
}

test('two players play a whole game until X wins', async ({ browser }) => {
  const { host, guest } = await startGame(browser);

  await playMoves(host, guest, X_WINS);

  await expect(host.getByRole('heading', { name: 'You won!' })).toBeVisible();
  await expect(guest.getByRole('heading', { name: 'The other player won' })).toBeVisible();
  await expect(host.getByText('Score 1 – 0')).toBeVisible();
  await expect(guest.getByText('Score 0 – 1')).toBeVisible();

  // Nobody can move once the game is over.
  await expect(guest.locator('.cell--playable')).toHaveCount(0);
  await expect(host.locator('.cell--playable')).toHaveCount(0);
});

test('a rematch starts a fresh game with O opening', async ({ browser }) => {
  const { host, guest } = await startGame(browser);
  await playMoves(host, guest, X_WINS);

  await host.getByRole('button', { name: 'Play again' }).click();
  await expect(host.getByRole('button', { name: 'Waiting for the other player…' })).toBeDisabled();
  await expect(guest.getByText('The other player wants to play again.', { exact: true }).first()).toBeVisible();
  await guest.getByRole('button', { name: 'Play again' }).click();

  // The starting player alternates, so O moves first and the score carries over.
  await expect(guest.getByRole('heading', { name: 'Your move' })).toBeVisible();
  await expect(host.getByRole('heading', { name: 'Their move' })).toBeVisible();
  await expect(host.getByText('Score 1 – 0')).toBeVisible();
  await expect(host.locator('[aria-label*=": X"], [aria-label*=": O"]')).toHaveCount(0);
});

test('moves out of turn or in the wrong board are not possible', async ({ browser }) => {
  const { host, guest } = await startGame(browser);

  // O can't move first: the cell isn't playable, so clicking does nothing.
  await cell(guest, 4, 4).click({ force: true });
  await expect(cell(host, 4, 4)).toHaveAttribute('aria-label', /empty/);

  // After X plays cell 8, O has to answer in board 8, not elsewhere.
  await cell(host, 3, 8).click();
  await expect(guest.getByText('Play in the bottom right board.')).toBeVisible();
  await cell(guest, 0, 0).click({ force: true });
  await expect(cell(host, 0, 0)).toHaveAttribute('aria-label', /empty/);
});

test('on a phone with tap-to-zoom switched on, the first tap zooms into a board and the second places the mark', async ({ browser }) => {
  const room = randomRoom();
  const host = await openPlayer(browser, room);
  const context = await browser.newContext({
    baseURL: 'http://localhost:5173',
    viewport: { width: 375, height: 700 },
    hasTouch: true,
    isMobile: true,
  });
  await context.addInitScript(() => localStorage.setItem('uttt-locale', 'en'));
  const guest = await context.newPage();
  await guest.goto(`/${room}`);
  // Tap-to-zoom is off by default; switch it on in the settings.
  await guest.getByRole('button', { name: 'Settings' }).click();
  await guest.getByRole('checkbox', { name: 'Tap a board to zoom in' }).check();
  await guest.getByRole('button', { name: 'Close' }).click();
  await expect(host.getByText('The other player has joined.', { exact: true })).toBeVisible();
  await host.getByRole('button', { name: 'Start game' }).click();
  await guest.getByRole('button', { name: 'Start game' }).click();
  await expect(host.getByRole('heading', { name: 'Your move' })).toBeVisible();

  await cell(host, 3, 8).click();
  await expect(guest.getByRole('heading', { name: 'Your move' })).toBeVisible();

  // Forced into board 8. The first tap only zooms in...
  await cell(guest, 8, 0).tap();
  await expect(cell(guest, 8, 0)).toHaveAttribute('aria-label', /empty/);
  await expect
    .poll(async () => (await cell(guest, 8, 0).boundingBox())!.width)
    .toBeGreaterThan(44);

  // ...the second one plays and zooms back out.
  await cell(guest, 8, 0).tap();
  await expect(cell(guest, 8, 0)).toHaveAttribute('aria-label', /: O/);
  await expect(guest.getByRole('button', { name: 'Zoom out' })).toHaveCount(0);
});
